#!/usr/bin/env node
// One walk through the whole product, over HTTPS through Caddy, against the drill stack:
//
//   deploy/drill/stack.sh run node deploy/drill/journey.mjs [interview|analysis|requirements|all]
//
//   interview     three participants, each a full interview over REST + SSE (open, consent, turns to
//                 the end), the summary read back
//   analysis      the admin starts an analysis on the campaign and waits for the worker to finish it
//   requirements  a requirements session is run to its end, a specification version is generated by
//                 the worker, and its PDF is fetched (which draws the diagrams through the Kroki pair)
//
// Exits non-zero on the first failed expectation. Prints one JSON line per step with timings.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { ADMIN_EMAIL, Client, log, percentile, signIn, sleep, staff } from "./lib.mjs";

const dir = process.env.AIDP_DRILL_DIR;
const campaign = JSON.parse(readFileSync(join(dir, "campaign.json"), "utf8"));
const ANSWERS = [
  "I am a ward clerk on a cardiology ward. Most of my day is keeping bed status current.",
  "We print the list, write changes on it by hand, then type everything in again at the end of the shift.",
  "It takes about forty minutes every shift and mistakes slip in. Last week a bed was shown free when it was not.",
  "The tools are a shared spreadsheet and the hospital system, which do not talk to each other.",
  "Yes, nurses ask me the same question about discharges many times a day, usually by phone.",
  "If one screen showed the status for the whole ward, most of that would go away.",
  "I would worry about patient data. It must stay inside the hospital network.",
  "That is about everything I can think of right now.",
];
const results = [];
const step = async (name, fn) => {
  const started = Date.now();
  try {
    const detail = await fn();
    const row = { step: name, ok: true, ms: Date.now() - started, ...detail };
    results.push(row);
    log(JSON.stringify(row));
    return detail;
  } catch (e) {
    const row = { step: name, ok: false, ms: Date.now() - started, error: String(e.message ?? e) };
    results.push(row);
    log(JSON.stringify(row));
    process.exitCode = 1;
    throw e;
  }
};

/** One participant, from the link to the end of the interview. */
export async function participant(index, maxTurns = 30) {
  const p = new Client(`participant-${index}`);
  const arrival = await p.ok("GET", `/api/participant/p/${campaign.linkToken}`);
  if (arrival.status !== "open") throw new Error(`campaign link is ${arrival.status}`);
  await p.ok("POST", `/api/participant/p/${campaign.linkToken}/open`, {});
  if (![...p.jar.keys()].some((k) => k.includes("aidp_participant")))
    throw new Error("no participant cookie after open");
  await p.ok("POST", "/api/participant/p/session/consent", {
    consentVersion: arrival.campaign.consentVersion ?? "v1",
    participantFields: { name: `Drill ${index}`, role: "clerk" },
    participationChoice: "anonymous",
  });
  const firstTokens = [];
  let turns = 0;
  let ended = false;
  let input;
  while (!ended && turns < maxTurns) {
    const out = await p.turn("/api/participant/p/session/turns", input);
    if (out.error || out.status !== 200)
      throw new Error(`turn ${turns} failed: ${JSON.stringify(out.error)}`);
    if (!out.message?.content) throw new Error(`turn ${turns} produced no message`);
    if (/<<<TURN_META|TURN_META/.test(out.message.content))
      throw new Error("turn metadata leaked to the participant");
    if (out.firstTokenMs !== null) firstTokens.push(out.firstTokenMs);
    ended = out.ended;
    turns += 1;
    input = { content: ANSWERS[(turns - 1) % ANSWERS.length], modality: "text" };
    await sleep(600);
  }
  if (!ended) throw new Error(`interview did not end within ${maxTurns} turns`);
  const view = await p.ok("GET", "/api/participant/p/session");
  const summary = await p.json("GET", "/api/participant/p/session/summary");
  return {
    turns,
    firstTokenP50: percentile(firstTokens, 50),
    firstTokenMax: Math.max(...firstTokens),
    status: view.status ?? view.session?.status,
    summaryStatus: summary.status,
  };
}

async function interviews() {
  const out = [];
  for (let i = 1; i <= 3; i++) {
    out.push(await step(`interview ${i}`, () => participant(i)));
  }
  return out;
}

async function analysis(admin) {
  await step("analysis: queued and finished", async () => {
    const created = await staff(admin, "POST", `/campaigns/${campaign.campaignId}/analyses`, {});
    const id = created.analysis?.id ?? created.id;
    const deadline = Date.now() + 5 * 60_000;
    for (;;) {
      const list = await staff(admin, "GET", `/campaigns/${campaign.campaignId}/analyses`);
      const row = (list.analyses ?? []).find((a) => !id || a.id === id) ?? list.analyses?.[0];
      if (row && ["done", "failed", "error"].includes(row.status)) {
        if (row.status !== "done") throw new Error(`analysis ended as ${row.status}: ${row.error ?? ""}`);
        return { analysisId: row.id, stats: row.stats };
      }
      if (Date.now() > deadline)
        throw new Error(`analysis still ${row?.status ?? "missing"} after 5 minutes`);
      await sleep(2000);
    }
  });
}

async function requirements(admin) {
  let sessionId;
  await step("requirements: interview to its end", async () => {
    const created = await staff(admin, "POST", "/requirements", {
      title: "Drill: bed status board",
      prompt: "A single screen that shows bed status for a whole ward, so the clerk records it once.",
      path: "nontechnical",
    });
    sessionId = created.session.id;
    let input;
    let turns = 0;
    let ended = false;
    while (!ended && turns < 60) {
      const out = await admin.turn(`/api/staff/requirements/${sessionId}/turns`, input);
      if (out.error) throw new Error(`requirements turn ${turns}: ${JSON.stringify(out.error)}`);
      ended = out.ended;
      turns += 1;
      input = { content: ANSWERS[(turns - 1) % ANSWERS.length], modality: "text" };
      // A person takes a few seconds to answer; the route allows 20 turns a minute.
      await sleep(3200);
    }
    if (!ended) {
      await staff(admin, "POST", `/requirements/${sessionId}/complete`);
    }
    return { sessionId, turns, ended };
  });
  await step("requirements: specification generated by the worker", async () => {
    const queued = await staff(admin, "POST", `/requirements/${sessionId}/versions`, { label: "drill" });
    const deadline = Date.now() + 5 * 60_000;
    for (;;) {
      const list = await staff(admin, "GET", `/requirements/${sessionId}/versions`);
      const v = list.versions.find((x) => x.version === queued.version.version);
      if (v && (v.status === "done" || v.status === "failed")) {
        if (v.status !== "done") throw new Error(`version ${v.version} failed: ${v.error ?? ""}`);
        return { version: v.version, stats: v.stats };
      }
      if (Date.now() > deadline) throw new Error(`version still ${v?.status ?? "missing"}`);
      await sleep(2000);
    }
  });
  await step("requirements: PDF through the diagram renderer", async () => {
    const list = await staff(admin, "GET", `/requirements/${sessionId}/versions`);
    const v = list.versions.find((x) => x.status === "done");
    const res = await admin.fetch(
      `/api/staff/requirements/${sessionId}/versions/${v.version}/export?format=pdf`,
    );
    const bytes = Buffer.from(await res.arrayBuffer());
    if (res.status !== 200)
      throw new Error(`pdf export answered ${res.status}: ${bytes.toString().slice(0, 200)}`);
    if (bytes.subarray(0, 4).toString() !== "%PDF") throw new Error("the export is not a PDF");
    return { bytes: bytes.length, contentType: res.headers.get("content-type") };
  });
}

const which = process.argv[2] ?? "all";
try {
  if (which === "interview" || which === "all") await interviews();
  if (which === "analysis" || which === "all" || which === "requirements") {
    const admin = await signIn(ADMIN_EMAIL, "admin");
    if (which !== "requirements") await analysis(admin);
    if (which === "requirements" || which === "all") await requirements(admin);
  }
} catch {
  // reported by `step`
}
console.log(JSON.stringify({ summary: results.map((r) => ({ step: r.step, ok: r.ok, ms: r.ms })) }));
